"""Inventory import pipeline: CSV rows to validated stock records."""
from __future__ import annotations

import csv
import logging
from dataclasses import dataclass, field
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Iterable, Iterator

log = logging.getLogger(__name__)


class RowError(ValueError):
    """A CSV row that cannot be turned into a record."""

    def __init__(self, line: int, reason: str) -> None:
        super().__init__(f"line {line}: {reason}")
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class StockRecord:
    sku: str
    name: str
    quantity: int
    unit_price: Decimal
    tags: tuple[str, ...] = field(default_factory=tuple)

    @property
    def value(self) -> Decimal:
        return self.unit_price * self.quantity


def parse_row(line: int, row: dict[str, str]) -> StockRecord:
    sku = row.get("sku", "").strip().upper()
    if not sku:
        raise RowError(line, "missing sku")
    name = row.get("name", "").strip()
    if not name:
        raise RowError(line, f"missing name for {sku}")
    try:
        quantity = int(row.get("quantity", "0"))
    except ValueError:
        raise RowError(line, f"bad quantity {row.get('quantity')!r}") from None
    if quantity < 0:
        raise RowError(line, f"negative quantity for {sku}")
    try:
        unit_price = Decimal(row.get("unit_price", "0"))
    except InvalidOperation:
        raise RowError(line, f"bad price {row.get('unit_price')!r}") from None
    tags = tuple(t.strip() for t in row.get("tags", "").split(";") if t.strip())
    return StockRecord(sku, name, quantity, unit_price, tags)


def parse_rows(rows: Iterable[dict[str, str]]) -> Iterator[StockRecord]:
    for index, row in enumerate(rows, start=2):
        try:
            yield parse_row(index, row)
        except RowError as err:
            log.warning("skipping %s", err)


def load_inventory(path: Path) -> list[StockRecord]:
    with path.open(newline="", encoding="utf-8") as handle:
        return list(parse_rows(csv.DictReader(handle)))


def total_value(records: Iterable[StockRecord]) -> Decimal:
    return sum((r.value for r in records), Decimal("0"))


def by_tag(records: Iterable[StockRecord]) -> dict[str, list[StockRecord]]:
    groups: dict[str, list[StockRecord]] = {}
    for record in records:
        for tag in record.tags:
            groups.setdefault(tag, []).append(record)
    return groups

//! A small blocking connection pool.

use std::collections::VecDeque;
use std::sync::{Arc, Condvar, Mutex};
use std::time::{Duration, Instant};

use crate::conn::{Connection, ConnectError};

pub const DEFAULT_MAX_SIZE: usize = 10;
pub const DEFAULT_ACQUIRE_TIMEOUT: Duration = Duration::from_secs(5);

#[derive(Debug)]
pub enum PoolError {
    Timeout,
    Connect(ConnectError),
}

struct Inner {
    idle: VecDeque<Connection>,
    open: usize,
}

pub struct Pool {
    inner: Mutex<Inner>,
    available: Condvar,
    max_size: usize,
    timeout: Duration,
    url: String,
}

impl Pool {
    pub fn new(url: impl Into<String>) -> Arc<Self> {
        Self::with_limits(url, DEFAULT_MAX_SIZE, DEFAULT_ACQUIRE_TIMEOUT)
    }

    pub fn with_limits(url: impl Into<String>, max_size: usize, timeout: Duration) -> Arc<Self> {
        Arc::new(Pool {
            inner: Mutex::new(Inner { idle: VecDeque::new(), open: 0 }),
            available: Condvar::new(),
            max_size,
            timeout,
            url: url.into(),
        })
    }

    pub fn acquire(self: &Arc<Self>) -> Result<Pooled, PoolError> {
        let deadline = Instant::now() + self.timeout;
        let mut inner = self.inner.lock().unwrap();
        loop {
            if let Some(conn) = inner.idle.pop_front() {
                return Ok(Pooled { conn: Some(conn), pool: Arc::clone(self) });
            }
            if inner.open < self.max_size {
                inner.open += 1;
                drop(inner);
                return match Connection::open(&self.url) {
                    Ok(conn) => Ok(Pooled { conn: Some(conn), pool: Arc::clone(self) }),
                    Err(err) => {
                        self.inner.lock().unwrap().open -= 1;
                        self.available.notify_one();
                        Err(PoolError::Connect(err))
                    }
                };
            }
            let now = Instant::now();
            if now >= deadline {
                return Err(PoolError::Timeout);
            }
            inner = self.available.wait_timeout(inner, deadline - now).unwrap().0;
        }
    }

    fn release(&self, conn: Connection) {
        let mut inner = self.inner.lock().unwrap();
        if conn.is_broken() {
            inner.open -= 1;
        } else {
            inner.idle.push_back(conn);
        }
        self.available.notify_one();
    }
}

pub struct Pooled {
    conn: Option<Connection>,
    pool: Arc<Pool>,
}

impl Drop for Pooled {
    fn drop(&mut self) {
        if let Some(conn) = self.conn.take() {
            self.pool.release(conn);
        }
    }
}

